class Almacen:
    def __init__(self):
        self.datos = {}
        self.aof = []  # Append Only File: registro de cada comando

    def set(self, clave, valor):
        self.datos[clave] = valor
        self.aof.append(f"SET {clave} {valor}")

    def snapshot_rdb(self):
        # Foto completa del estado en este instante
        return dict(self.datos)

    def reconstruir_desde_aof(self):
        estado = {}
        for comando in self.aof:
            _, clave, valor = comando.split(" ", 2)
            estado[clave] = valor
        return estado

almacen = Almacen()
almacen.set("usuario:1", "activo")
rdb = almacen.snapshot_rdb()
almacen.set("usuario:2", "activo")  # ocurre despues del snapshot

print(f"RDB tiene {len(rdb)} claves: {sorted(rdb)}")
recuperado = almacen.reconstruir_desde_aof()
print(f"AOF reconstruye {len(recuperado)} claves: {sorted(recuperado)}")
print(f"Comandos en AOF: {len(almacen.aof)}")
